mod rocq_int63 {
//! Trusted runtime for Rocq's 63-bit primitive integers.
//!
//! Every incoming word must be canonical: `0 <= x < 2^63`. This includes words
//! returned by other host replacements. `of_u64` explicitly reduces a host word.
//! No allocation, reference counting, or host-observable state is involved.
//!
//! Word and Ordering results have extraction registrations. Rocq comparison
//! constructors map to Ordering::{Equal, Less, Greater}. Native Rust bool,
//! Carry and division-tuple results below still need extraction ABI mappings.
//! The mulc bridge constructs an ordinary source pair from scalar projections.

use std::cmp::Ordering;

pub type Word = u64;
pub const BITS: u32 = 63;
pub const MASK: Word = (1u64 << BITS) - 1;

#[inline]
pub const fn of_u64(x: u64) -> Word {
    x & MASK
}

/// Interpret bit 62 as the sign bit, without changing the stored word.
#[inline]
const fn signed(x: Word) -> i64 {
    ((x << 1) as i64) >> 1
}

#[inline]
pub const fn lsl(x: Word, shift: Word) -> Word {
    if shift < BITS as Word {
        (x << shift) & MASK
    } else {
        0
    }
}

#[inline]
pub const fn lsr(x: Word, shift: Word) -> Word {
    if shift < BITS as Word {
        x >> shift
    } else {
        0
    }
}

#[inline]
pub const fn asr(x: Word, shift: Word) -> Word {
    // Rocq returns zero for an out-of-range shift, even for negative words.
    if shift < BITS as Word {
        (signed(x) >> shift) as Word & MASK
    } else {
        0
    }
}

#[inline]
pub const fn land(x: Word, y: Word) -> Word {
    x & y
}
#[inline]
pub const fn lor(x: Word, y: Word) -> Word {
    x | y
}
#[inline]
pub const fn lxor(x: Word, y: Word) -> Word {
    x ^ y
}

#[inline]
pub const fn add(x: Word, y: Word) -> Word {
    x.wrapping_add(y) & MASK
}
#[inline]
pub const fn sub(x: Word, y: Word) -> Word {
    x.wrapping_sub(y) & MASK
}
#[inline]
pub const fn mul(x: Word, y: Word) -> Word {
    x.wrapping_mul(y) & MASK
}

#[inline]
pub const fn div(x: Word, y: Word) -> Word {
    if y == 0 {
        0
    } else {
        x / y
    }
}

#[inline]
pub const fn modulo(x: Word, y: Word) -> Word {
    if y == 0 {
        x
    } else {
        x % y
    }
}

#[inline]
pub const fn divs(x: Word, y: Word) -> Word {
    // A signed 63-bit minimum divided by -1 fits in i64; masking restores the
    // 63-bit result, including that overflow case. Division truncates to zero.
    if y == 0 {
        0
    } else {
        signed(x).wrapping_div(signed(y)) as Word & MASK
    }
}

#[inline]
pub const fn mods(x: Word, y: Word) -> Word {
    if y == 0 {
        x
    } else {
        signed(x).wrapping_rem(signed(y)) as Word & MASK
    }
}

#[inline]
pub const fn addmuldiv(shift: Word, x: Word, y: Word) -> Word {
    // Also handles shift=0 (x), shift=63 (y), and shift>63 (zero).
    lor(lsl(x, shift), lsr(y, sub(BITS as Word, shift)))
}

#[inline]
pub const fn head0(x: Word) -> Word {
    (x.leading_zeros() - 1) as Word
}
#[inline]
pub const fn tail0(x: Word) -> Word {
    if x == 0 {
        BITS as Word
    } else {
        x.trailing_zeros() as Word
    }
}

#[inline]
pub const fn eqb(x: Word, y: Word) -> bool {
    x == y
}
#[inline]
pub const fn ltb(x: Word, y: Word) -> bool {
    x < y
}
#[inline]
pub const fn leb(x: Word, y: Word) -> bool {
    x <= y
}
#[inline]
pub const fn ltsb(x: Word, y: Word) -> bool {
    signed(x) < signed(y)
}
#[inline]
pub const fn lesb(x: Word, y: Word) -> bool {
    signed(x) <= signed(y)
}
#[inline]
pub fn compare(x: Word, y: Word) -> Ordering {
    x.cmp(&y)
}
#[inline]
pub fn compares(x: Word, y: Word) -> Ordering {
    signed(x).cmp(&signed(y))
}

/// C1 indicates a carry for addition and a borrow for subtraction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Carry {
    C0(Word),
    C1(Word),
}

#[inline]
pub const fn addc(x: Word, y: Word) -> Carry {
    let sum = x as u128 + y as u128;
    let word = sum as Word & MASK;
    if sum >> BITS == 0 {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn addcarryc(x: Word, y: Word) -> Carry {
    let sum = x as u128 + y as u128 + 1;
    let word = sum as Word & MASK;
    if sum >> BITS == 0 {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn subc(x: Word, y: Word) -> Carry {
    let word = sub(x, y);
    if x >= y {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

#[inline]
pub const fn subcarryc(x: Word, y: Word) -> Carry {
    let word = sub(sub(x, y), 1);
    if x > y {
        Carry::C0(word)
    } else {
        Carry::C1(word)
    }
}

/// Exact product, high word first, in base 2^63 (not 2^64).
#[inline]
pub const fn mulc(x: Word, y: Word) -> (Word, Word) {
    let product = x as u128 * y as u128;
    ((product >> BITS) as Word, product as Word & MASK)
}

/// Scalar ABI projections; the frontend constructs the ordinary Rocq pair.
#[inline]
pub const fn mulc_high(x: Word, y: Word) -> Word {
    mulc(x, y).0
}
#[inline]
pub const fn mulc_low(x: Word, y: Word) -> Word {
    mulc(x, y).1
}

#[inline]
pub const fn diveucl(x: Word, y: Word) -> (Word, Word) {
    (div(x, y), modulo(x, y))
}

/// Divide a two-word numerator by a word. Rocq returns (0,0) when high>=y,
/// including division by zero; otherwise both quotient and remainder fit.
#[inline]
pub const fn diveucl_21(high: Word, low: Word, y: Word) -> (Word, Word) {
    if high >= y {
        return (0, 0);
    }
    let numerator = ((high as u128) << BITS) | low as u128;
    (
        (numerator / y as u128) as Word,
        (numerator % y as u128) as Word,
    )
}

/// Scalar ABI projections; the frontend constructs the ordinary Rocq pair.
#[inline]
pub const fn diveucl_21_quotient(high: Word, low: Word, y: Word) -> Word {
    diveucl_21(high, low, y).0
}

#[inline]
pub const fn diveucl_21_remainder(high: Word, low: Word, y: Word) -> Word {
    diveucl_21(high, low, y).1
}

}

mod rocq_array {
//! EXPERIMENTAL: writes revoke old array versions instead of copying buffers.
//! Not a refinement of persistent Rocq arrays or the OwnedANF CoW host contract.
//! Only arrays are revoked; ordinary Rc aliasing of other values is unchanged.
#![cfg_attr(not(feature = "unguarded-copy"), forbid(unsafe_code))]
#![deny(unsafe_op_in_unsafe_fn)]

use std::cell::{Ref, RefCell};
use std::rc::Rc;

pub const MAX_LENGTH: u64 = 4_194_303;

#[cold]
#[inline(never)]
fn stale_access(operation: &str, handle: u64, current: u64) -> ! {
    panic!("stale array access ({operation}): handle={handle}, current={current}")
}

#[cold]
#[inline(never)]
fn read_while_borrowed() -> ! {
    panic!("strong array read while mutably borrowed")
}

#[cfg(feature = "unguarded-copy")]
enum ReadFailure {
    Borrowed,
    Stale(u64, u64),
}

/// A checked read scope. References cannot outlive the guard, and writes are
/// rejected until it is dropped. No user callback is run by view accessors.
pub struct ReadView<'a, T> {
    storage: Ref<'a, Storage<T>>,
}

impl<T> ReadView<'_, T> {
    #[inline(always)]
    pub fn get(&self, index: u64) -> &T {
        self.storage
            .elements
            .get(usize::try_from(index).unwrap_or(usize::MAX))
            .unwrap_or(&self.storage.default)
    }

    pub fn length(&self) -> u64 {
        self.storage.elements.len() as u64
    }

    pub fn default(&self) -> &T {
        &self.storage.default
    }
}

/// All aliases of a header share its fixed version. A shared header is never
/// refreshed by a write: the writer receives a new header for the same storage.
pub struct Array<T> {
    version: u64,
    storage: Rc<RefCell<Storage<T>>>,
}

struct Storage<T> {
    version: u64,
    elements: Vec<T>,
    default: T,
}

impl<T> Array<T> {
    pub fn literal(default: T, elements: Vec<T>) -> Self {
        assert!(
            elements.len() as u64 <= MAX_LENGTH,
            "array literal exceeds Rocq maximum"
        );
        Self {
            version: 0,
            storage: Rc::new(RefCell::new(Storage {
                version: 0,
                elements,
                default,
            })),
        }
    }

    #[inline(always)]
    fn read(&self, operation: &str) -> Ref<'_, Storage<T>> {
        let storage = match self.storage.try_borrow() {
            Ok(storage) => storage,
            Err(_) => read_while_borrowed(),
        };
        self.check_version(&storage, operation);
        storage
    }

    #[inline(always)]
    fn check_version(&self, storage: &Storage<T>, operation: &str) {
        if self.version != storage.version {
            stale_access(operation, self.version, storage.version);
        }
    }

    pub fn read_view(&self) -> ReadView<'_, T> {
        ReadView {
            storage: self.read("read_view"),
        }
    }

    /// # Safety
    /// `read` must only access fields/slices and copy values, without mutating
    /// storage or returning a reference into it. While access is active, neither
    /// the operation nor its captures may run user Clone/Drop code, callbacks,
    /// allocation or panic formatting: these could reenter `set`.
    ///
    /// The uncounted borrow does not prevent a subsequent mutable borrow. Rc
    /// excludes cross-thread access, but preventing same-thread reentrancy is
    /// the caller's responsibility. Keep all failure formatting in `finish_copy`,
    /// after this function has returned and the storage reference has ended.
    #[cfg(feature = "unguarded-copy")]
    #[inline(always)]
    unsafe fn copy_storage<R: Copy>(
        &self,
        read: impl FnOnce(&Storage<T>) -> R,
    ) -> Result<R, ReadFailure> {
        // SAFETY: Rc makes this single-threaded. The standard-library check
        // rejects an active mutable borrow. The private callers execute no
        // user code or mutation before the reference ends, return no storage
        // reference, and copy without invoking T::clone. Existing counted host
        // guards still block writes, but this uncounted reference itself does
        // not: its lifetime must contain no opportunity to reenter set. The
        // version check detects stale handles; it cannot protect a live &Storage
        // from mutation. Current callers satisfy the contract above.
        let storage = match unsafe { self.storage.try_borrow_unguarded() } {
            Ok(storage) => storage,
            Err(_) => return Err(ReadFailure::Borrowed),
        };
        if self.version != storage.version {
            return Err(ReadFailure::Stale(self.version, storage.version));
        }
        Ok(read(storage))
    }

    #[cfg(feature = "unguarded-copy")]
    #[inline(always)]
    fn finish_copy<R>(result: Result<R, ReadFailure>, operation: &str) -> R {
        match result {
            Ok(value) => value,
            Err(ReadFailure::Borrowed) => read_while_borrowed(),
            Err(ReadFailure::Stale(handle, current)) => stale_access(operation, handle, current),
        }
    }

    #[inline(always)]
    pub fn get_copy(&self, index: u64) -> T
    where
        T: Copy,
    {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: only copy an existing element/default; no Clone, user
            // callback or escaping borrow. Error formatting is outside access.
            let result = unsafe {
                self.copy_storage(|s| {
                    *s.elements
                        .get(usize::try_from(index).unwrap_or(usize::MAX))
                        .unwrap_or(&s.default)
                })
            };
            Self::finish_copy(result, "get_copy")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            *self.get(index)
        }
    }

    pub fn default_copy(&self) -> T
    where
        T: Copy,
    {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: Copy performs no callback; the value does not borrow its slot.
            let result = unsafe { self.copy_storage(|s| s.default) };
            Self::finish_copy(result, "default_copy")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            *self.default()
        }
    }

    /// Host-only guarded access. Holding the guard makes writes panic *before*
    /// mutation. Generated get calls instead clone the value and release it.
    #[inline(always)]
    pub fn get(&self, index: u64) -> Ref<'_, T> {
        Ref::map(self.read("get"), |s| {
            s.elements
                .get(usize::try_from(index).unwrap_or(usize::MAX))
                .unwrap_or(&s.default)
        })
    }

    pub fn default(&self) -> Ref<'_, T> {
        Ref::map(self.read("default"), |s| &s.default)
    }

    pub fn length(&self) -> u64 {
        #[cfg(feature = "unguarded-copy")]
        {
            // SAFETY: read scalar Vec metadata only, without invoking element code.
            let result = unsafe { self.copy_storage(|s| s.elements.len() as u64) };
            Self::finish_copy(result, "length")
        }
        #[cfg(not(feature = "unguarded-copy"))]
        {
            self.read("length").elements.len() as u64
        }
    }
}

pub fn make<T: Clone>(length: u64, default: T) -> Rc<Array<T>> {
    Rc::new(Array::literal(
        default.clone(),
        vec![default; length.min(MAX_LENGTH) as usize],
    ))
}

// Expose the guard's lifetime and cleanup to the monomorphized caller. The
// version/bounds/borrow checks remain; this does not assume unique array use.
#[inline(always)]
pub fn set<T>(mut array: Rc<Array<T>>, index: u64, value: T) -> Rc<Array<T>> {
    let mut storage = array
        .storage
        .try_borrow_mut()
        .expect("strong array write while borrowed");
    array.check_version(&storage, "set");
    let index = usize::try_from(index)
        .ok()
        .filter(|&i| i < storage.elements.len());
    let Some(index) = index else {
        drop(storage);
        return array;
    };
    let version = storage
        .version
        .checked_add(1)
        .expect("strong array version overflow");
    // Revoke first: if dropping the overwritten host value panics, no old
    // version can subsequently observe the partially completed write as valid.
    storage.version = version;
    storage.elements[index] = value;
    drop(storage);
    if let Some(header) = Rc::get_mut(&mut array) {
        header.version = version;
        array
    } else {
        Rc::new(Array {
            version,
            storage: Rc::clone(&array.storage),
        })
    }
}

#[inline(always)]
pub fn get<T: Clone>(array: &Rc<Array<T>>, index: u64) -> T {
    T::clone(&array.get(index))
}

#[inline(always)]
pub fn get_copy<T: Copy>(array: &Rc<Array<T>>, index: u64) -> T {
    array.get_copy(index)
}

pub fn length<T>(array: &Rc<Array<T>>) -> u64 {
    array.length()
}

pub fn default<T: Clone>(array: &Rc<Array<T>>) -> T {
    T::clone(&array.default())
}

/// Independent *shallow* buffer copy, like Marray.copy. Nested array/other Rc
/// elements remain aliases; this does not recursively snapshot their payloads.
pub fn copy<T: Clone>(array: &Rc<Array<T>>) -> Rc<Array<T>> {
    let storage = array.read("copy");
    Rc::new(Array::literal(
        storage.default.clone(),
        storage.elements.clone(),
    ))
}


}

mod rocq_string {
//! Immutable byte strings; owning values use Rc<RocqString>, never UTF-8 str.
use std::rc::Rc;
use std::cmp::Ordering;

/// Rocq's portable primitive-string limit (also used on 64-bit hosts).
pub const MAX_LENGTH: usize = 16_777_211;

#[derive(Debug)]
pub struct RocqString {
    bytes: Box<[u8]>,
}

impl RocqString {
    pub fn from_bytes(bytes: Vec<u8>) -> Self {
        assert!(
            bytes.len() <= MAX_LENGTH,
            "Rocq primitive string exceeds max_length"
        );
        Self {
            bytes: bytes.into_boxed_slice(),
        }
    }
}

pub fn length(s: &Rc<RocqString>) -> u64 {
    s.bytes.len() as u64
}

pub fn get(s: &Rc<RocqString>, index: u64) -> u64 {
    usize::try_from(index)
        .ok()
        .and_then(|i| s.bytes.get(i))
        .copied()
        .unwrap_or(0) as u64
}

/// Rocq clamps the length and takes the low eight bits of the character.
pub fn make(length: u64, byte: u64) -> Rc<RocqString> {
    let length = length.min(MAX_LENGTH as u64) as usize;
    Rc::new(RocqString::from_bytes(vec![byte as u8; length]))
}

/// Unsigned lexicographic byte ordering, including embedded NULs.
pub fn compare(left: &Rc<RocqString>, right: &Rc<RocqString>) -> Ordering {
    left.bytes.cmp(&right.bytes)
}

/// Preserve all of the left string and the longest representable right prefix.
pub fn cat(left: &Rc<RocqString>, right: &Rc<RocqString>) -> Rc<RocqString> {
    let extra = right.bytes.len().min(MAX_LENGTH - left.bytes.len());
    let mut bytes = Vec::with_capacity(left.bytes.len() + extra);
    bytes.extend_from_slice(&left.bytes);
    bytes.extend_from_slice(&right.bytes[..extra]);
    Rc::new(RocqString::from_bytes(bytes))
}


}

